export async function loadDictionary(language) {
  if (dictionaries[language]) return {dictionary:dictionaries[language],automatic:false};
  const response=await fetch('/api/translate',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({target:language,source:'en',items:dictionaries.en})});
  const result=await response.json();
  if(!response.ok || !result.items || result.unavailable) throw new Error('translation_unavailable');
  return {dictionary:{...dictionaries.en,...result.items},automatic:true};
}


